mapper.select:
SELECT bet_info betinfo, SUM(chip) totalbet
FROM lottery_count
where lottery_id = #{lotteryId}
  and issue = #{issue}
  and member_id = #{memberId}
GROUP BY bet_info

SELECT bet_info betinfo, sum(chip) totalbet, agent
FROM lottery_count
where issue = #{issue}
  and lottery_id = #{lotteryId}
GROUP BY bet_info
